=== FILE: debounce_rca_repro.v ===
`timescale 1ns / 1ps
// Repro for prj-a26914b30e:root-cause.
// Spec (debounce header): a change on `noisy`, in either direction, restarts
// the count, so a pulse of STABLE edges or fewer, high or low, never reaches
// `clean`. Checks sample only settled values, away from the STABLE boundary.
module debounce_rca_repro;
    reg  clk   = 1'b0;
    reg  rst   = 1'b1;
    reg  noisy = 1'b0;
    wire clean;

    debounce #(.STABLE(4)) dut (
        .clk  (clk),
        .rst  (rst),
        .noisy(noisy),
        .clean(clean)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    reg [8*64-1:0] nonce;

    task check(input expected, input [8*24-1:0] what);
        begin
            if (clean === expected)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL t=%0t %0s: clean=%b expected %b", $time, what, clean, expected);
            end
        end
    endtask

    // Drive `noisy` to v for n cycles. At each negedge, optionally check
    // clean (the result of the previous posedge) before driving.
    task drive(input v, input integer n, input integer chk, input exp, input [8*24-1:0] what);
        integer i;
        begin
            for (i = 0; i < n; i = i + 1) begin
                @(negedge clk);
                if (chk) check(exp, what);
                noisy = v;
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        rst = 1'b1;
        noisy = 1'b0;
        repeat (3) @(negedge clk);
        rst = 1'b0;

        // Settle high: clean must become 1.
        drive(1'b1, 12, 0, 1'b0, "settle high");
        @(negedge clk);
        check(1'b1, "settled high");

        // Low glitch of 3 edges (<= STABLE): clean must stay 1 throughout.
        drive(1'b0, 3, 1, 1'b1, "during low glitch");
        drive(1'b1, 15, 1, 1'b1, "after low glitch");

        // Settle low: clean must become 0.
        drive(1'b0, 12, 0, 1'b0, "settle low");
        @(negedge clk);
        check(1'b0, "settled low");

        // High glitch of 3 edges (<= STABLE): clean must stay 0 throughout.
        drive(1'b1, 3, 1, 1'b0, "during high glitch");
        drive(1'b0, 15, 1, 1'b0, "after high glitch");

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
